using System;using System.Diagnostics;using System.IO;using System.Linq;using System.Reflection;using System.Runtime.InteropServices;using System.Windows;using System.Windows.Controls;using System.Windows.Interop;using System.Windows.Media;using System.Windows.Threading;using TrayLeaf;
class GlassPerformanceTests {
 static int failed,passed; static void Check(bool b,string s){Console.WriteLine((b?"PASS ":"FAIL ")+s);if(b)passed++;else failed++;}
 static void Pump(int ms){var frame=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};t.Tick+=delegate{t.Stop();frame.Continue=false;};t.Start();Dispatcher.PushFrame(frame);}
 [DllImport("user32.dll")] static extern bool GetWindowDisplayAffinity(IntPtr h,out uint v);
 static bool Matches(Border surface,Color color){var brush=surface.Background as DrawingBrush;if(brush==null)return false;var group=brush.Drawing as DrawingGroup;if(group==null)return false;var drawing=group.Children[0] as ImageDrawing;var image=drawing==null?null:drawing.ImageSource as System.Windows.Media.Imaging.BitmapSource;if(image==null)return false;var p=new byte[4];image.CopyPixels(new Int32Rect(image.PixelWidth/2,image.PixelHeight/2,1,1),p,4,0);return Math.Abs(p[0]-color.B)<=1&&Math.Abs(p[1]-color.G)<=1&&Math.Abs(p[2]-color.R)<=1;}
 static object Field(Window w,string name){var all=(System.Collections.IEnumerable)typeof(DesktopGlass).GetField("sessions",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);foreach(var session in all){var type=session.GetType();if((Window)type.GetField("Window",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(session)==w){var field=type.GetField(name,BindingFlags.Instance|BindingFlags.NonPublic);return field==null?null:field.GetValue(session);}}return null;}
 static byte[] Reference(byte[] a,int width,int height){byte[] src=(byte[])a.Clone();for(int pass=0;pass<2;pass++){var dst=new byte[src.Length];for(int y=0;y<height;y++)for(int x=0;x<width;x++){for(int c=0;c<3;c++){int sum=0;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++)sum+=src[(Math.Max(0,Math.Min(height-1,y+dy))*width+Math.Max(0,Math.Min(width-1,x+dx)))*4+c];dst[(y*width+x)*4+c]=(byte)(sum/9);}dst[(y*width+x)*4+3]=255;}src=dst;}return src;}
 [STAThread] static int Main(string[] args){try{new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var random=new Random(19041);foreach(var size in new[]{new[]{1,1},new[]{2,7},new[]{13,9},new[]{220,150}}){var a=new byte[size[0]*size[1]*4];random.NextBytes(a);var copy=(byte[])a.Clone();var expected=Reference(a,size[0],size[1]);var actual=DesktopGlass.Blur(a,size[0],size[1]);Check(actual.SequenceEqual(expected),"exact-two-pass-blur-"+size[0]+"x"+size[1]);Check(a.SequenceEqual(copy),"input-unchanged-"+size[0]+"x"+size[1]);}
 var pixels=new byte[220*150*4];random.NextBytes(pixels);for(int i=0;i<3;i++)DesktopGlass.Blur(pixels,220,150);var sw=Stopwatch.StartNew();for(int i=0;i<80;i++)DesktopGlass.Blur(pixels,220,150);sw.Stop();double blurMs=sw.Elapsed.TotalMilliseconds/80;Console.WriteLine("METRIC blur_220x150_ms="+blurMs.ToString("F3",System.Globalization.CultureInfo.InvariantCulture));
 Check(typeof(DesktopGlass).GetMethod("FrameInterval",BindingFlags.Static|BindingFlags.NonPublic)!=null,"adaptive-frame-policy-present");
 var pattern=new Window{Title="TrayLeaf glass benchmark background",Width=1100,Height=760,Left=110,Top=90,WindowStartupLocation=WindowStartupLocation.Manual,Topmost=true,ShowInTaskbar=false,Background=Brushes.CornflowerBlue};pattern.Show();var surface=new Border{Name="WindowSurface",CornerRadius=new CornerRadius(22)};var w=new Window{Title="TrayLeaf glass benchmark",Width=800,Height=500,Left=150,Top=130,WindowStartupLocation=WindowStartupLocation.Manual,WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=Brushes.Transparent,Topmost=true,ShowInTaskbar=false,Content=surface};NameScope.SetNameScope(w,new NameScope());w.RegisterName("WindowSurface",surface);w.Resources["Canvas"]=new SolidColorBrush(Color.FromRgb(30,38,52));w.Resources["Text"]=Brushes.White;w.Show();w.Activate();DesktopGlass.Set(w,true);int n=0;var animate=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(33)};animate.Tick+=delegate{n++;pattern.Background=new SolidColorBrush(Color.FromRgb((byte)(n*19%255),(byte)(n*37%255),(byte)(n*53%255)));};animate.Start();Pump(600);Console.WriteLine("METRIC window_active="+w.IsActive);int first=DesktopGlass.Frames(w);var proc=Process.GetCurrentProcess();var cpu=proc.TotalProcessorTime;sw.Restart();Pump(3600);double seconds=sw.Elapsed.TotalSeconds;double fps=(DesktopGlass.Frames(w)-first)/seconds;double cpuMs=(proc.TotalProcessorTime-cpu).TotalMilliseconds;Console.WriteLine("METRIC animated_frames="+(DesktopGlass.Frames(w)-first));Console.WriteLine("METRIC animated_fps="+fps.ToString("F2",System.Globalization.CultureInfo.InvariantCulture));Console.WriteLine("METRIC process_cpu_ms="+cpuMs.ToString("F1",System.Globalization.CultureInfo.InvariantCulture));Check(fps>=12,"animated-backdrop-at-least-12fps");Check(surface.Background is DrawingBrush,"real-backdrop-brush");animate.Stop();var lags=new System.Collections.Generic.List<double>();for(int i=0;i<10;i++){Pump(17+(i*7)%40);var color=Color.FromRgb((byte)(11+i*17),(byte)(221-i*13),(byte)(37+i*11));pattern.Background=new SolidColorBrush(color);var lag=Stopwatch.StartNew();while(!Matches(surface,color)&&lag.ElapsedMilliseconds<1200)Pump(2);lags.Add(lag.Elapsed.TotalMilliseconds);Check(Matches(surface,color),"sampled-background-colors-not-self-"+i);}Console.WriteLine("METRIC color_change_mean_ms="+lags.Average().ToString("F2",System.Globalization.CultureInfo.InvariantCulture));Console.WriteLine("METRIC color_change_max_ms="+lags.Max().ToString("F2",System.Globalization.CultureInfo.InvariantCulture));
 pattern.Background=Brushes.CornflowerBlue;Pump(1100);first=DesktopGlass.Frames(w);Pump(450);var staticFrames=DesktopGlass.Frames(w)-first;Console.WriteLine("METRIC unchanged_published_frames="+staticFrames);var policy=typeof(DesktopGlass).GetMethod("FrameInterval",BindingFlags.Static|BindingFlags.NonPublic);if(policy!=null){Check((int)policy.Invoke(null,new object[]{true,0,false})==16,"active-fast-cadence");Check((int)policy.Invoke(null,new object[]{true,4,false})==125,"static-backoff");Check((int)policy.Invoke(null,new object[]{false,0,false})==100,"inactive-backoff");Check((int)policy.Invoke(null,new object[]{false,4,true})==16,"motion-overrides-backoff");Check(staticFrames==0,"unchanged-backdrop-skips-texture-publication");}
 w.Hide();Pump(350);Check(!((DispatcherTimer)Field(w,"timer")).IsEnabled,"hidden-timer-stops");first=DesktopGlass.Frames(w);Pump(450);Check(DesktopGlass.Frames(w)==first,"hidden-does-not-publish-frames");w.Show();DesktopGlass.Set(w,true);Pump(350);w.WindowState=WindowState.Minimized;Pump(350);Check(!((DispatcherTimer)Field(w,"timer")).IsEnabled,"minimized-timer-stops");first=DesktopGlass.Frames(w);Pump(450);Check(DesktopGlass.Frames(w)==first,"minimized-does-not-publish-frames");w.WindowState=WindowState.Normal;Pump(250);for(int i=0;i<12;i++){w.Left=150+i;w.Width=800+i*2;Pump(4);}pattern.Background=Brushes.Goldenrod;var settle=Stopwatch.StartNew();while(!Matches(surface,Colors.Goldenrod)&&settle.ElapsedMilliseconds<1500)Pump(10);Check(Matches(surface,Colors.Goldenrod),"latest-geometry-replaces-stale-capture");
 if(policy!=null){var capture=Field(w,"buffer");var dcField=capture.GetType().GetField("Dc",BindingFlags.Instance|BindingFlags.NonPublic);var dc=(IntPtr)dcField.GetValue(capture);Pump(350);Check(dc!=IntPtr.Zero&&(IntPtr)dcField.GetValue(capture)==dc,"same-size-reuses-gdi-buffer");}
 DesktopGlass.Set(w,false);Pump(200);uint affinity;GetWindowDisplayAffinity(new WindowInteropHelper(w).Handle,out affinity);Check(affinity==0,"display-affinity-restored");Check(!DesktopGlass.Active(w),"disabled-session-released");first=DesktopGlass.Frames(w);Pump(150);Check(DesktopGlass.Frames(w)==first,"late-capture-does-not-reapply-after-disable");w.Close();pattern.Close();Console.WriteLine("RESULT passed="+passed+" failed="+failed);return failed==0?0:1;}catch(Exception e){Console.Error.WriteLine(e);return 2;}}
}
